package codex

import (
	"bufio"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"github.com/inferal-oss/agent-session-migrator/internal/domain"
	"github.com/inferal-oss/agent-session-migrator/internal/gitwork"
	"io"
	"os"
	"os/exec"
	"time"
)

// domain.Project methods are generated by `codex app-server generate-json-schema
// --experimental`. This is a normal stdio client over SSH, not a database edit.
func registerRemoteProject(parent context.Context, p domain.Preparation, name, root string) (string, error) {
	ctx, cancel := context.WithTimeout(parent, 60*time.Second)
	defer cancel()
	remote := gitwork.ShellQuote(p.Executable) + " app-server --stdio"
	cmd := exec.CommandContext(ctx, "ssh", "-oBatchMode=yes", "-oConnectTimeout=15", "--", p.SSHTarget, remote)
	cmd.Stderr = os.Stderr
	in, err := cmd.StdinPipe()
	if err != nil {
		return "", err
	}
	out, err := cmd.StdoutPipe()
	if err != nil {
		return "", err
	}
	if err = cmd.Start(); err != nil {
		return "", err
	}
	defer func() { in.Close(); cmd.Process.Kill(); cmd.Wait() }()
	scanner := bufio.NewScanner(out)
	scanner.Buffer(make([]byte, 4096), 16*1024*1024)
	seq := 0
	call := func(method string, params any, result any) error {
		seq++
		id := seq
		b, err := json.Marshal(map[string]any{"id": id, "method": method, "params": params})
		if err != nil {
			return err
		}
		if _, err = in.Write(append(b, '\n')); err != nil {
			return err
		}
		for scanner.Scan() {
			var reply struct {
				ID     int             `json:"id"`
				Result json.RawMessage `json:"result"`
				Error  json.RawMessage `json:"error"`
				Method string          `json:"method"`
			}
			if err = json.Unmarshal(scanner.Bytes(), &reply); err != nil {
				return fmt.Errorf("unexpected app-server output: %w", err)
			}
			if reply.ID != id {
				continue
			}
			if len(reply.Error) > 0 {
				return fmt.Errorf("app-server %s: %s", method, string(reply.Error))
			}
			return json.Unmarshal(reply.Result, result)
		}
		if err = scanner.Err(); err != nil {
			return err
		}
		return errors.New("app-server closed before responding")
	}
	var init json.RawMessage
	if err = call("initialize", map[string]any{"clientInfo": map[string]string{"name": "agent_session_migrator", "version": "0.1.0"}, "capabilities": map[string]bool{"experimentalApi": true}}, &init); err != nil {
		return "", err
	}
	if _, err = io.WriteString(in, "{\"method\":\"initialized\"}\n"); err != nil {
		return "", err
	}
	cursor := ""
	for {
		params := map[string]any{"limit": 100}
		if cursor != "" {
			params["cursor"] = cursor
		}
		var list struct {
			Data []struct {
				ID    string `json:"id"`
				Roots []struct {
					Path string `json:"path"`
				} `json:"roots"`
			} `json:"data"`
			NextCursor *string `json:"nextCursor"`
		}
		if err = call("project/list", params, &list); err != nil {
			return "", err
		}
		for _, project := range list.Data {
			for _, r := range project.Roots {
				if r.Path == root {
					return project.ID, nil
				}
			}
		}
		if list.NextCursor == nil || *list.NextCursor == "" {
			break
		}
		if *list.NextCursor == cursor {
			return "", errors.New("project pagination did not advance")
		}
		cursor = *list.NextCursor
	}
	sum := sha256.Sum256([]byte(root))
	var created struct {
		Project struct {
			ID    string `json:"id"`
			Roots []struct {
				Path string `json:"path"`
			} `json:"roots"`
		} `json:"project"`
	}
	if err = call("project/create", map[string]any{"idempotencyKey": "agent-session-migrator-" + hex.EncodeToString(sum[:]), "name": name, "roots": []map[string]string{{"path": root}}}, &created); err != nil {
		return "", err
	}
	for _, r := range created.Project.Roots {
		if r.Path == root && created.Project.ID != "" {
			return created.Project.ID, nil
		}
	}
	return "", errors.New("created project did not confirm the requested root")
}
